function parseLog(log) {
    const requests = log
       .split('\n')
       .filter((line) =>!line.startsWith('#'))
       .map((line) => {
            const [timestamp, method, path, statusCode, latency] = line.split(' ');
            const date = new Date(timestamp);
            const time = date.toTimeString();
            const timeOnly = time.slice(0, 5);
            const timeStart = new Date(date.toUTCString());
            timeStart.setHours(18, 0, 0, 0);
            const timeEnd = new Date(date.toUTCString());
            timeEnd.setHours(18, 59, 59, 999);
            const timeInRange = timeStart <= timeOnly && timeOnly <= timeEnd;

            return {
                timeOnly,
                method,
                path,
                statusCode,
                latency,
                timeInRange,
            };
        })
       .filter((req) => req.timeInRange);

    const pathStatusCounts = {};

    requests.forEach((req) => {
        const path = req.path;
        const statusCode = req.statusCode;

        if (!pathStatusCounts[path]) {
            pathStatusCounts[path] = {};
        }

        if (!pathStatusCounts[path][statusCode]) {
            pathStatusCounts[path][statusCode] = 0;
        }

        pathStatusCounts[path][statusCode]++;
    });

    const filteredPathStatusCounts = {};

    Object.keys(pathStatusCounts).forEach((path) => {
        const statusCounts = pathStatusCounts[path];
        const filteredStatusCounts = {};

        Object.keys(statusCounts).forEach((statusCode) => {
            const count = statusCounts[statusCode];
            if (count > 0) {
                filteredStatusCounts[statusCode] = count;
            }
        });

        if (Object.keys(filteredStatusCounts).length > 0) {
            filteredPathStatusCounts[path] = filteredStatusCounts;
        }
    });

    return filteredPathStatusCounts;
}

